={
  "model": "openai/gpt-4o-mini",
  "temperature": 0.2,
  "response_format": {
    "type": "json_object"
  },
  "messages": [
    {
      "role": "system",
      "content": "You are a customer support AI agent.

Answer the user question only using the provided knowledge base context.

The confidence value represents how strongly the knowledge base supports the answer.

Confidence rules:
- 0.8 to 1.0: The retrieved context directly answers the question.
- 0.4 to 0.7: The retrieved context partially helps answer the question.
- 0.0 to 0.3: The retrieved context does not contain enough information.

If the knowledge base does not contain the answer, clearly state that the information is unavailable and assign low confidence.

Return only valid JSON with these fields:
{
  "answer": "string",
  "confidence": number
}"
    },
    {
      "role": "user",
      "content": "Question: {{$node['Webhook'].json.body.query}}

Knowledge Base Context:
{{$json.sources.map(s => s.content).join('\n\n')}}

Return JSON format:
{
  "answer": "your answer",
  "confidence": 0.0
}"
    }
  ]
}

parameters.jsCode:
const llmResponse = JSON.parse(
  $json.choices[0].message.content
);

return [
  {
    json: {
      answer: llmResponse.answer,
      confidence: llmResponse.confidence,

      token_usage: {
        prompt: $json.usage.prompt_tokens,
        completion: $json.usage.completion_tokens,
        total: $json.usage.total_tokens
      },

      sources: $node["Similarity Search"].json.sources
    }
  }
];

return [
  {
    json: {
      action: "answered",
      answer: $json.answer,
      confidence: $json.confidence,
      sources: $json.sources,
      token_usage: $json.token_usage
    }
  }
];

return [
{
json:{
action:"ticket_created",

ticket:{
ticket_id:$json.ticket_id,
status:$json.status,
message:$json.message
},

token_usage:
$node["Parse AI Response"].json.token_usage,

message:
"Your query was forwarded to support because confidence was below the threshold."
}
}
];

return [
  {
    json: {
      error: "Embedding service unavailable",
      details: $json.error?.message || "Failed to generate query embedding"
    }
  }
];

return [
  {
    json: {
      error: "LLM service unavailable",
      details: $json.error?.message || "Failed to generate AI response"
    }
  }
];

return [
  {
    json: {
      error: "Ticket creation failed",
      details: $json.error?.message || "Support system unavailable"
    }
  }
];

return [
  {
    json: {
      error: "Invalid LLM JSON response",
      details: $json.error?.message || "Unable to parse AI response"
    }
  }
];

const start = $node["Start Timer"].json.startTime;

const latency = DateTime.now()
  .diff(DateTime.fromISO(start), "milliseconds")
  .milliseconds;

return [
{
  json: {

    // Original response
    response: $input.first().json,

    // Logging fields
    timestamp: new Date().toISOString(),

    userQuery: $node["Webhook"].json.body.query,

    retrievedDocs: $node["Parse AI Response"].json.sources
      .map(s => s.content)
      .join("\n\n"),

    generatedAnswer: $node["Parse AI Response"].json.answer,

    inputTokens: $node["Parse AI Response"].json.token_usage.prompt,

    outputTokens: $node["Parse AI Response"].json.token_usage.completion,

    totalTokens: $node["Parse AI Response"].json.token_usage.total,

    status: "success",

    errorMessage: null,

    responseLatencyMs: latency
  }
}
];

const start =
$node["Start Timer"].json.startTime;

const latency =
DateTime.now()
.diff(
DateTime.fromISO(start),
"milliseconds"
)
.milliseconds;

return [
{
json:{

timestamp:new Date().toISOString(),

userQuery:
$node["Webhook"].json.body.query,

retrievedDocs:null,

generatedAnswer:null,

inputTokens:0,

outputTokens:0,

totalTokens:0,

status:"error",

errorMessage:
$json.error + " - " + $json.details,

responseLatencyMs:latency

}
}
];
